import java.util.*;

class Solution {
    public ListNode partition(ListNode head, int pivot) {
        ListNode smallHead = new ListNode(0), bigHead = new ListNode(0);
        ListNode s = smallHead, b = bigHead;
        for (ListNode cur = head; cur != null; cur = cur.next) {
            if (cur.val < pivot) { s.next = cur; s = cur; }  // goes in the small chain
            else { b.next = cur; b = cur; }                 // goes in the big chain
        }
        b.next = null;                 // big chain ends the list
        s.next = bigHead.next;         // small chain, then big chain
        return smallHead.next;
    }
}

