class Solution:
    def partition(self, head: Optional[ListNode], pivot: int) -> Optional[ListNode]:
        s = st = ListNode(0); b = bt = ListNode(0)
        while head:
            if head.val < pivot: st.next = head; st = head
            else: bt.next = head; bt = head
            head = head.next
        bt.next = None; st.next = b.next
